ST.xhtml:p:
R_Trigger0(CLK := g_biYDFeeingAbsOpen);
R_Trigger1(CLK := g_biYDFeeingAbsClose);

IF R_Trigger0.Q THEN
  g_boYDFeeingAbsDone := FALSE;
  nSwitchState := 1;
END_IF;

IF R_Trigger1.Q THEN
  g_boYDFeeingAbsDone := FALSE;
  g_bGeneral2ABSClose := TRUE;
  nSwitchState := 3;
END_IF;

g_General2_Override.Enable := TRUE;

CASE nSwitchState OF
  0:
  nSwitchState := 0;
  1:
  g_bGeneral2ABSDone:=FALSE;
  IF LREAL_TO_INT(g_biYDFeeingAbsType) = 0 THEN
    g_fGeneral2ABSPos := g_General2_Axis.NCTOPLC.SETPOS + g_dYDHeadLength;
    g_fGeneral2ABSVel := dAbsVelocity;
    nSwitchState := 5;
  ELSIF LREAL_TO_INT(g_biYDFeeingAbsType) = 1 THEN
    g_fGeneral2ABSPos := g_dYDPartLength;
    dTargetPos := dSlowDownDis;
    g_fGeneral2ABSVel := dAbsVelocity;
    nSwitchState := 2;
  ELSIF LREAL_TO_INT(g_biYDFeeingAbsType) = 2 THEN
    g_fGeneral2ABSPos := g_General2_Axis.NCTOPLC.SETPOS + g_dYDTailLength;
    g_fGeneral2ABSVel := dAbsVelocity;
    nSwitchState := 5;
  ELSIF LREAL_TO_INT(g_biYDFeeingAbsType) = 3 THEN
    g_fGeneral2ABSPos := 0.0;
    g_fGeneral2ABSVel := dAbsVelocity;
    nSwitchState := 5;
  END_IF;
  2:
  g_bGeneral2ABSOpen := TRUE;

  IF g_bGeneral2ABSDone THEN
    g_General2_Override.VelFactor := 1.0;
    g_bGeneral2ABSOpen := FALSE;
    g_boYDFeeingAbsDone := TRUE;
    nSwitchState := 0;
  END_IF;
  3:
  Ton_Delay(IN := TRUE,PT := T#10ms);
  IF Ton_Delay.Q THEN
    Ton_Delay(IN := FALSE);
    g_bGeneral2ABSClose := FALSE;
    nSwitchState := 0;
  END_IF;
  5:
  g_bGeneral2ABSOpen := TRUE;
  IF g_General2_Axis.NCTOPLC.ACTPOS <= dTargetPos THEN
    g_General2_Override.VelFactor := dGeneral2Override;
  END_IF;

  IF g_bGeneral2ABSDone THEN
    g_General2_Override.VelFactor := 1.0;
    g_bGeneral2ABSOpen := FALSE;
    g_boYDFeeingAbsDone := TRUE;
    nSwitchState := 0;
  END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  Ton_Delay(IN := FALSE);
  g_bGeneral2ABSOpen := FALSE;
  g_bGeneral2ABSClose := FALSE;
  g_General2_Override.VelFactor := 1.0;
  nSwitchState := 0;
END_IF;
